mapper.select:
SELECT id, name, mobile, time, visitor, type, status, create_time, remark FROM reservation WHERE 1 = 1
AND status = #{status}
ORDER BY create_time DESC

SELECT
    id, name, mobile, time, visitor, type, status,
    create_time, update_time, create_by, update_by, remark
FROM reservation
WHERE name = #{name}
  AND mobile = #{mobile}
  AND time = #{time}
  AND visitor = #{visitor}
  AND status = 0
LIMIT 1

SELECT id, name, mobile, time, visitor, type, status, create_time, remark FROM reservation WHERE 1 = 1
AND name LIKE CONCAT('%', #{name}, '%')
AND mobile = #{phone}
AND time >= FROM_UNIXTIME(#{startTime}/1000)
AND time <= FROM_UNIXTIME(#{endTime}/1000)
AND status = #{status}
AND type = #{type}
ORDER BY create_time DESC
